#' Age Pyramid
#'
#' 
#' @param data .
#' @param age .
#' @param gender .
#' @param female .
#' @param male .
#' @param age_groups .
#' @param age_interval .
#' @param bin_width .
#' @param custom_breaks .
#' @param pct_base .
#' @param plot_values .
#' @param plot_title .
#' @param showplot .
#' @param showInterpretation .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$dataSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$population} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$assignment} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$pyramid} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dataSummary$asDF}
#'
#' \code{as.data.frame(results$dataSummary)}
#'
#' @export
pyagepyramid <- function(
    data,
    age = NULL,
    gender = NULL,
    female,
    male,
    age_groups = "custom",
    age_interval = "left",
    bin_width = 5,
    custom_breaks = "",
    pct_base = "within_gender",
    plot_values = "count",
    plot_title = "Age Pyramid",
    showplot = TRUE,
    showInterpretation = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyagepyramid requires jmvcore to be installed (restart may be required)")

    if ( ! missing(age)) age <- jmvcore::resolveQuo(jmvcore::enquo(age))
    if ( ! missing(gender)) gender <- jmvcore::resolveQuo(jmvcore::enquo(gender))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(age), age, NULL),
            `if`( ! missing(gender), gender, NULL))

    for (v in gender) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyagepyramidOptions$new(
        age = age,
        gender = gender,
        female = female,
        male = male,
        age_groups = age_groups,
        age_interval = age_interval,
        bin_width = bin_width,
        custom_breaks = custom_breaks,
        pct_base = pct_base,
        plot_values = plot_values,
        plot_title = plot_title,
        showplot = showplot,
        showInterpretation = showInterpretation,
        showConsole = showConsole)

    analysis <- pyagepyramidClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

